import { useCallback, useEffect, useRef, useState } from 'react';

import { KPI } from 'domain/Filter/FilterRules/constants/kpiRules';
import { usePageFilterManagement } from 'hooks';
import { FilterForm, FilterValue } from 'models/Filters';

import { PERFORMANCE_TOOL_PAGE_NAME } from '../../constants';

interface MarketShareValues {
  zone: FilterValue;
  country: FilterValue;
  weight_type: FilterValue;
}

const isAbiZone = (zone: FilterValue) => zone === 'ABI';

export const useMarketShareWeightTypeAlert = (
  applied: FilterForm,
  enabled = true,
  suppressInitialAlert = false,
) => {
  const previousMarketShareRef = useRef<MarketShareValues | null>(null);
  const hasInitializedRef = useRef(false);
  const { applyDirect } = usePageFilterManagement(PERFORMANCE_TOOL_PAGE_NAME);
  const [isOpen, setIsOpen] = useState(false);
  const close = useCallback(() => {
    setIsOpen(false);
  }, []);

  useEffect(() => {
    const isMarketShare =
      applied.kpis === KPI.MARKET_SHARE ||
      applied.kpis === KPI.MARKET_SHARE_OFFICIAL;

    if (!enabled || !isMarketShare) {
      previousMarketShareRef.current = null;
      setIsOpen(false);
      return;
    }

    const currentState = {
      zone: applied.zone,
      country: applied.country,
      weight_type: applied.weight_type,
    };

    if (suppressInitialAlert && !hasInitializedRef.current) {
      hasInitializedRef.current = true;
      previousMarketShareRef.current = currentState;
      return;
    }

    const previousState = previousMarketShareRef.current;

    if (!previousState) {
      previousMarketShareRef.current = currentState;
      return;
    }

    const crossedAbiBoundary =
      isAbiZone(previousState.zone) !== isAbiZone(currentState.zone);
    const expectedWeightType = isAbiZone(currentState.zone)
      ? 'industry'
      : 'budget';
    const weightTypeChanged = currentState.weight_type !== expectedWeightType;

    previousMarketShareRef.current = currentState;
    if (crossedAbiBoundary && weightTypeChanged) {
      setIsOpen(true);
      applyDirect({ weight_type: expectedWeightType });
    }
  }, [
    applied.country,
    applied.kpis,
    applied.weight_type,
    applied.zone,
    applyDirect,
    enabled,
    suppressInitialAlert,
  ]);

  return { isOpen, close };
};
